use std::{env,fs};use wasmc_owned_algorithms_component::{Lib,wasmtime};use wasmc_owned_algorithms_component::exports::wasmc::owned_algorithms::algorithms::Request;use wasmtime::{Engine,Store};use wasmtime::component::{Component,Linker};
fn main(){let args:Vec<_>=env::args().collect();let engine=Engine::default();let component=Component::new(&engine,fs::read(&args[1]).unwrap()).unwrap();let mut store=Store::new(&engine,());let lib=Lib::instantiate(&mut store,&component,&Linker::new(&engine)).unwrap();let f=lib.wasmc_owned_algorithms_algorithms();for n in [8,1048577,3145728,11]{let values=vec![-3;n];assert_eq!(f.call_sum_s32(&mut store,&values).unwrap(),-(n as i64)*3);let req=Request{label:"x".repeat(n),values:vec![1,-3,4],enabled:true};assert_eq!(f.call_request_score(&mut store,&req).unwrap(),(n as i64)*1000+102);}println!("{{\"accepted\":true,\"engine\":\"wasmtime-component\",\"largest_list_and_text\":3145728,\"same_instance_new_inputs\":true}}");}
